    INSERT INTO public.case_studies (topic_id, title, scenario, "order") VALUES (v_topic_id, 'Acute Blood Loss', 'A 23-year-old man is brought to the ED after a road traffic accident with acute blood loss. He is pale and tachycardic.', 1) RETURNING id INTO v_case_id;
