    INSERT INTO public.case_studies (topic_id, title, scenario, "order") VALUES (v_topic_id, 'High Altitude Adaptation', 'A 28-year-old man travels rapidly to a high-altitude region and remains there for several weeks.', 2) RETURNING id INTO v_case_id;
