    INSERT INTO public.case_studies (topic_id, title, scenario, "order") VALUES (v_topic_id, 'Iron Deficiency and Oxygen Transport', 'A 26-year-old woman with menorrhagia presents with fatigue and exertional dyspnea. Labs suggest iron deficiency anemia.', 3) RETURNING id INTO v_case_id;
