    INSERT INTO public.case_studies (topic_id, title, scenario, "order") VALUES (v_topic_id, 'Carbon Monoxide Exposure', 'A family is brought to the hospital after exposure to smoke from a faulty heater.', 4) RETURNING id INTO v_case_id;
