    INSERT INTO public.case_studies (topic_id, title, scenario, "order") VALUES (v_topic_id, 'Fetal Hemoglobin', 'A pregnant woman asks why fetal hemoglobin is beneficial in utero.', 5) RETURNING id INTO v_case_id;
    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'Compared with adult hemoglobin, fetal hemoglobin has:', '["Lower affinity for oxygen", "Higher affinity for oxygen", "No heme groups", "Greater carbon monoxide binding only", "Reduced iron content"]'::jsonb, 1, 'The correct answer is B.');
