    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'Rh sensitization usually affects which pregnancy more severely?', '["First pregnancy most often", "Subsequent Rh-positive pregnancies", "Only twin pregnancies", "Only preterm pregnancies", "Never affects fetus"]'::jsonb, 1, 'The correct answer is B.');
    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'The prevention strategy works by giving anti-D immunoglobulin to:', '["Rh-positive mothers only", "Rh-negative mothers at risk of sensitization", "Rh-positive newborns only", "ABO-incompatible fathers", "All neonates"]'::jsonb, 1, 'The correct answer is B.');
    INSERT INTO public.case_studies (topic_id, title, scenario, "order") VALUES (v_topic_id, 'ESR and Plasma Proteins', 'A patient with chronic inflammatory disease has elevated erythrocyte sedimentation rate (ESR).', 23) RETURNING id INTO v_case_id;
    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'ESR rises when rouleaux formation increases due to elevated:', '["Hemoglobin only", "Plasma proteins such as fibrinogen", "Platelet factor 4", "Sodium only", "Bilirubin only"]'::jsonb, 1, 'The correct answer is B.');
    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'Rouleaux refers to RBCs:', '["Undergoing hemolysis", "Stacking like coins", "Fragmenting into schistocytes", "Sickling", "Losing iron"]'::jsonb, 1, 'The correct answer is B.');
    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'ESR is a nonspecific marker of:', '["Oxygen carrying capacity", "Inflammation", "Platelet function only", "Blood group incompatibility", "Bone marrow aplasia"]'::jsonb, 1, 'The correct answer is B.');
    INSERT INTO public.case_studies (topic_id, title, scenario, "order") VALUES (v_topic_id, 'Thrombocytopenia', 'A woman with immune thrombocytopenia presents with petechiae and gum bleeding.', 24) RETURNING id INTO v_case_id;
    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'Petechiae and mucosal bleeding are most consistent with a defect in:', '["Secondary hemostasis only", "Primary hemostasis / platelet function", "RBC production only", "Fibrinolysis only", "Iron metabolism"]'::jsonb, 1, 'The correct answer is B.');
    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'A low platelet count primarily impairs:', '["Oxygen transport", "Initial platelet plug formation", "Bilirubin metabolism", "Antibody synthesis", "Erythropoietin release"]'::jsonb, 1, 'The correct answer is B.');
    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'Platelets also contribute to clot retraction through contractile proteins including:', '["Spectrin only", "Actin and myosin-like elements", "Elastin and fibrillin", "Keratin only", "Hemoglobin chains"]'::jsonb, 1, 'The correct answer is B.');
    INSERT INTO public.case_studies (topic_id, title, scenario, "order") VALUES (v_topic_id, 'Hematopoiesis Across Life', 'A medical student reviews where blood cells are formed during fetal life and after birth.', 25) RETURNING id INTO v_case_id;
    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'The primary site of hematopoiesis in normal adults is:', '["Liver", "Spleen", "Bone marrow", "Thymus", "Lymph node"]'::jsonb, 2, 'The correct answer is C.');
    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'In fetal life, a major hematopoietic organ before marrow dominance is the:', '["Pancreas", "Liver", "Thyroid", "Kidney", "Lung"]'::jsonb, 1, 'The correct answer is B.');
    INSERT INTO public.case_questions (case_id, question, options, correct_index, explanation) VALUES (v_case_id, 'All formed elements of blood arise ultimately from:', '["Mesothelial cells", "Hematopoietic stem cells", "Mature lymphocytes", "Plasma cells", "Osteoclast precursors only"]'::jsonb, 1, 'The correct answer is B.');
